// 308:       type.raw_type
// 309:     else
// 310:       # This isn't allowed unless whitelisted_for_underspecification is
// 311:       # true, due to the check in prop_validate_definition
// 312:       Object
// 313:     end
// 314:   end
// 315:
// 316:   # Returns `true` when the type of the prop is nilable, or the field is typed
// 317:   # as `T.untyped`, a `:default` is present in the rules hash, and its value is
// 318:   # `nil`. The latter case is a workaround for explicitly not supporting the use
// 319:   # of `T.nilable(T.untyped)`.
// 320:   #
// 321:   # checked(:never) - Rules hash is expensive to check
// 322:   sig do
// 323:     params(
// 324:       cls: PropTypeOrClass,
// 325:       rules: Rules,
// 326:     )
// 327:     .returns(T.anything)
// 328:     .checked(:never)
// 329:   end
// 330:   private def prop_nilable?(cls, rules)
// 331:     # NB: `prop` and `const` do not `T::Utils::coerce the type of the prop if it is a `Module`,
// 332:     # hence the bare `NilClass` check.
// 333:     T::Utils::Nilable.is_union_with_nilclass(cls) || ((cls == T.untyped || cls == NilClass) && rules.key?(:default) && rules[:default].nil?)
// 334:   end
// 335:
// 336:   sig(:final) { params(name: Symbol).returns(T::Boolean).checked(:never) }
// 337:   private def method_defined_on_ancestor?(name)
// 338:     (@class.method_defined?(name) || @class.private_method_defined?(name)) &&
// 339:       # Unfortunately, older versions of ruby don't allow the second parameter on
// 340:       # `private_method_defined?`.
// 341:       !@class.method_defined?(name, false) && !@class.private_method_defined?(name, false)
// 342:   end
// 343:
// 344:   sig(:final) { params(name: Symbol, rules: Rules).void.checked(:never) }
// 345:   private def validate_overrides(name, rules)
// 346:     override = elaborate_override(name, rules[:override])
// 347:
// 348:     return if rules[:without_accessors]
// 349:
// 350:     if override[:reader] && !method_defined_on_ancestor?(name) && !props.include?(name)
// 351:       raise ArgumentError.new("You marked the getter for prop #{name.inspect} as `override`, but the method `#{name}` doesn't exist to be overridden.")
// 352:     end
// 353:
// 354:     # Properly, we should also check whether `props[name]` is immutable, but the old code didn't either.
// 355:     if !rules[:immutable] && override[:writer] && !method_defined_on_ancestor?("#{name}=".to_sym) && !props.include?(name)
// 356:       raise ArgumentError.new("You marked the setter for prop #{name.inspect} as `override`, but the method `#{name}=` doesn't exist to be overridden.")
// 357:     end
// 358:   end
// 359:
// 360:   # checked(:never) - Rules hash is expensive to check
// 361:   sig do
// 362:     params(
// 363:       name: T.any(Symbol, String),
// 364:       cls: PropTypeOrClass,
// 365:       rules: Rules,
// 366:     )
// 367:     .void
// 368:     .checked(:never)
// 369:   end
// 370:   def prop_defined(name, cls, rules={})
// 371:     cls = T::Utils.resolve_alias(cls)
// 372:
// 373:     if prop_nilable?(cls, rules)
// 374:       # :_tnilable is introduced internally for performance purpose so that clients do not need to call
// 375:       # T::Utils::Nilable.is_tnilable(cls) again.
// 376:       # It is strictly internal: clients should always use T::Props::Utils.required_prop?() or
// 377:       # T::Props::Utils.optional_prop?() for checking whether a field is required or optional.
// 378:       rules[:_tnilable] = true
// 379:     end
// 380:
// 381:     name = name.to_sym
// 382:     type = cls
// 383:     if !cls.is_a?(Module)
// 384:       cls = convert_type_to_class(cls)
// 385:     end
// 386:     type_object = smart_coerce(type, enum: rules[:enum])
// 387:
// 388:     prop_validate_definition!(name, cls, rules, type_object)
// 389:
// 390:     # Retrieve the possible underlying object with T.nilable.
// 391:     type = T::Utils::Nilable.get_underlying_type(type)
// 392:
// 393:     rules_sensitivity = rules[:sensitivity]
// 394:     sensitivity_and_pii = {sensitivity: rules_sensitivity}
// 395:     if !rules_sensitivity.nil?
// 396:       normalize = T::Configuration.normalize_sensitivity_and_pii_handler
// 397:       if normalize
// 398:         sensitivity_and_pii = normalize.call(sensitivity_and_pii)
// 399:
// 400:         # We check for Class so this is only applied on concrete
// 401:         # documents/models; We allow mixins containing props to not
// 402:         # specify their PII nature, as long as every class into which they
// 403:         # are ultimately included does.
// 404:         #
// 405:         if sensitivity_and_pii[:pii] && @class.is_a?(Class) && !T.unsafe(@class).contains_pii?
// 406:           raise ArgumentError.new(
// 407:             "Cannot define pii prop `#{@class}##{name}` because `#{@class}` is `contains_no_pii`"
// 408:           )
// 409:         end
// 410:       end
// 411:     end
// 412:
// 413:     rules[:type] = type
// 414:     rules[:type_object] = type_object
// 415:     rules[:accessor_key] = "@#{name}".to_sym
// 416:     rules[:sensitivity] = sensitivity_and_pii[:sensitivity]
// 417:     rules[:pii] = sensitivity_and_pii[:pii]
// 418:     rules[:extra] = rules[:extra]&.freeze
// 419:
// 420:     # extra arbitrary metadata attached by the code defining this property
// 421:
// 422:     # for backcompat (the `:array` key is deprecated but because the name is
// 423:     # so generic it's really hard to be sure it's not being relied on anymore)
// 424:     if type.is_a?(T::Types::TypedArray)
// 425:       inner = T::Utils::Nilable.get_underlying_type(type.type)
// 426:       if inner.is_a?(Module)
// 427:         rules[:array] = inner
// 428:       end
// 429:     end
// 430:
// 431:     setter_proc, value_validate_proc, bound_setter_proc = T::Props::Private::SetterFactory.build_setter_proc(@class, name, rules)
// 432:     setter_proc.freeze
// 433:     value_validate_proc.freeze
// 434:     bound_setter_proc.freeze
// 435:     rules[:value_validate_proc] = value_validate_proc
// 436:     # :setter_proc is a pre-existing rules key and is preserved as-is: the
// 437:     # 1-arity, self-bound proc used only to define the generated `name=`
// 438:     # instance setter via `define_method(&proc)` (its fast path). The net-new
// 439:     # :_bound_setter_proc is the 2-arity (instance, val) equivalent that every
// 440:     # other write goes through without instance_exec's per-call self-rebinding;
// 441:     # it is underscore-prefixed (like :_tnilable) so external code that replays
// 442:     # rules hashes back into prop() filters it out as internal.
// 443:     rules[:setter_proc] = setter_proc
// 444:     rules[:_bound_setter_proc] = bound_setter_proc
// 445:
// 446:     validate_overrides(name, rules)
// 447:     add_prop_definition(name, rules)
// 448:
// 449:     # NB: using `without_accessors` doesn't make much sense unless you also define some other way to
// 450:     # get at the property (e.g., Chalk::ODM::Document exposes `get` and `set`).
// 451:     define_getter_and_setter(name, rules) unless rules[:without_accessors]
// 452:
// 453:     handle_foreign_option(name, cls, rules, rules[:foreign]) if rules[:foreign]
// 454:     handle_redaction_option(name, rules[:redaction]) if rules[:redaction]
// 455:   end
// 456:
// 457:   # checked(:never) - Rules hash is expensive to check
// 458:   sig { params(name: Symbol, rules: Rules).void.checked(:never) }
// 459:   private def define_getter_and_setter(name, rules)
// 460:     T::Configuration.without_ruby_warnings do
// 461:       if !rules[:immutable]
// 462:         if method(:prop_set).owner != T::Props::Decorator
// 463:           d = @class.decorator
// 464:           @class.send(:define_method, "#{name}=") do |val|
// 465:             d.prop_set(self, name, val, rules)
// 466:           end
// 467:         else
// 468:           # Fast path (~4x faster as of Ruby 2.6)
// 469:           @class.send(:define_method, "#{name}=", &rules.fetch(:setter_proc))
// 470:         end
// 471:
// 472:       end
// 473:
// 474:       if method(:prop_get).owner != T::Props::Decorator || rules.key?(:ifunset)
// 475:         d = @class.decorator
// 476:         @class.send(:define_method, name) do
// 477:           d.prop_get(self, name, rules)
// 478:         end
// 479:       else
// 480:         # Fast path (~30x faster as of Ruby 2.6)
// 481:         @class.send(:attr_reader, name) # send is used because `attr_reader` is private in 2.4
// 482:       end
// 483:     end
// 484:   end
// 485:
// 486:   sig do
// 487:     params(type: PropTypeOrClass, enum: T.untyped)
// 488:     .returns(T::Types::Base)
// 489:     .checked(:never)
// 490:   end
// 491:   private def smart_coerce(type, enum:)
// 492:     # Backwards compatibility for pre-T::Types style
// 493:     type = T::Utils.coerce(type)
// 494:     if enum.nil?
// 495:       type
// 496:     else
// 497:       nonnil_type = T::Utils.unwrap_nilable(type)
// 498:       if nonnil_type
// 499:         T.unsafe(T.nilable(T.all(T.unsafe(nonnil_type), T.deprecated_enum(enum))))
// 500:       else
// 501:         T.unsafe(T.all(T.unsafe(type), T.deprecated_enum(enum)))
// 502:       end
// 503:     end
// 504:   end
// 505:
// 506:   # Create `#{prop_name}_redacted` method
// 507:   sig do
// 508:     params(
// 509:       prop_name: Symbol,
// 510:       redaction: T.untyped,
// 511:     )
// 512:     .void
// 513:     .checked(:never)
// 514:   end
// 515:   private def handle_redaction_option(prop_name, redaction)
// 516:     redacted_method = "#{prop_name}_redacted"
// 517:
// 518:     @class.send(:define_method, redacted_method) do
// 519:       value = self.public_send(prop_name)
// 520:       handler = T::Configuration.redaction_handler
// 521:       if !handler
// 522:         raise "Using `redaction:` on a prop requires specifying `T::Configuration.redaction_handler`"
// 523:       end
// 524:       handler.call(value, redaction)
// 525:     end
// 526:   end
// 527:
// 528:   sig do
// 529:     params(
// 530:       option_sym: Symbol,
// 531:       foreign: T.untyped,
// 532:       valid_type_msg: String,
// 533:     )
// 534:     .void
// 535:     .checked(:never)
// 536:   end
// 537:   private def validate_foreign_option(option_sym, foreign, valid_type_msg:)
// 538:     if foreign.is_a?(Symbol) || foreign.is_a?(String)
// 539:       raise ArgumentError.new(
// 540:         "Using a symbol/string for `#{option_sym}` is no longer supported. Instead, use a Proc " \
// 541:         "that returns the class, e.g., foreign: -> {Foo}"
// 542:       )
// 543:     end
// 544:
// 545:     if !foreign.is_a?(Proc) && !foreign.is_a?(Array) && !foreign.respond_to?(:load)
// 546:       raise ArgumentError.new("The `#{option_sym}` option must be #{valid_type_msg}")
// 547:     end
// 548:   end
// 549:
// 550:   # checked(:never) - Rules hash is expensive to check
// 551:   sig do
// 552:     params(
// 553:       prop_name: T.any(String, Symbol),
// 554:       rules: Rules,
// 555:       foreign: T.untyped,
// 556:     )
// 557:     .void
// 558:     .checked(:never)
// 559:   end
// 560:   private def define_foreign_method(prop_name, rules, foreign)
// 561:     fk_method = "#{prop_name}_"
// 562:
// 563:     # n.b. there's no clear reason *not* to allow additional options
// 564:     # here, but we're baking in `allow_direct_mutation` since we
// 565:     # *haven't* allowed additional options in the past and want to
// 566:     # default to keeping this interface narrow.
// 567:     foreign = T.let(foreign, T.untyped, checked: false)
// 568:     @class.send(:define_method, fk_method) do |allow_direct_mutation: nil|
// 569:       if foreign.is_a?(Proc)
// 570:         resolved_foreign = foreign.call
// 571:         if !resolved_foreign.respond_to?(:load)
// 572:           raise ArgumentError.new(
// 573:             "The `foreign` proc for `#{prop_name}` must return a model class. " \
// 574:             "Got `#{resolved_foreign.inspect}` instead."
// 575:           )
// 576:         end
// 577:         # `foreign` is part of the closure state, so this will persist to future invocations
// 578:         # of the method, optimizing it so this only runs on the first invocation.
// 579:         foreign = resolved_foreign
// 580:       end
// 581:       opts = if allow_direct_mutation.nil?
// 582:         {}
// 583:       else
// 584:         {allow_direct_mutation: allow_direct_mutation}
// 585:       end
// 586:
// 587:       T.unsafe(self.class).decorator.foreign_prop_get(self, prop_name, foreign, rules, opts)
// 588:     end
// 589:
// 590:     force_fk_method = "#{fk_method}!"
// 591:     @class.send(:define_method, force_fk_method) do |allow_direct_mutation: nil|
// 592:       loaded_foreign = send(fk_method, allow_direct_mutation: allow_direct_mutation)
// 593:       if !loaded_foreign
// 594:         raise("Failed to load foreign model method=#{force_fk_method} class=#{self.class}")
// 595:       end
// 596:       loaded_foreign
// 597:     end
// 598:   end
// 599:
// 600:   # checked(:never) - Rules hash is expensive to check
// 601:   sig do
// 602:     params(
// 603:       prop_name: Symbol,
// 604:       prop_cls: T::Module[T.anything],
// 605:       rules: Rules,
// 606:       foreign: T.untyped,
// 607:     )
// 608:     .void
// 609:     .checked(:never)
// 610:   end
// 611:   private def handle_foreign_option(prop_name, prop_cls, rules, foreign)
// 612:     validate_foreign_option(
// 613:       :foreign, foreign, valid_type_msg: "a model class or a Proc that returns one"
// 614:     )
// 615:
// 616:     if prop_cls != String
// 617:       raise ArgumentError.new("`foreign` can only be used with a prop type of String")
// 618:     end
// 619:
// 620:     if foreign.is_a?(Array)
// 621:       # We don't support arrays with `foreign` because it's hard to both preserve ordering and
// 622:       # keep them from being lurky performance hits by issuing a bunch of un-batched DB queries.
// 623:       # We could potentially address that by porting over something like AmbiguousIDLoader.
// 624:       raise ArgumentError.new(
// 625:         "Using an array for `foreign` is no longer supported. Instead, please use a union type of " \
// 626:         "token types for the prop type, e.g., T.any(Opus::Autogen::Tokens::FooModelToken, Opus::Autogen::Tokens::BarModelToken)"
// 627:       )
// 628:     end
// 629:
// 630:     unless foreign.is_a?(Proc)
// 631:       raise ArgumentError.new(<<~MESSAGE)
// 632:         Please use a Proc that returns a model class instead of the model class itself as the argument to `foreign`. In other words:
// 633:
// 634:           instead of `prop :foo, String, foreign: FooModel`
// 635:           use `prop :foo, String, foreign: -> {FooModel}`
// 636:
// 637:       MESSAGE
// 638:     end
// 639:
// 640:     define_foreign_method(prop_name, rules, foreign)
// 641:   end
// 642:
// 643:   # TODO: rename this to props_inherited
// 644:   #
// 645:   # This gets called when a module or class that extends T::Props gets included, extended,
// 646:   # prepended, or inherited.
// 647:   sig { params(child: T::Module[T.anything]).void.checked(:never) }
// 648:   def model_inherited(child)
// 649:     child.extend(T::Props::ClassMethods)
// 650:     child = T.cast(child, DecoratedClassType)
// 651:
// 652:     child.plugins.concat(decorated_class.plugins)
// 653:     decorated_class.plugins.each do |mod|
// 654:       # NB: apply_class_methods must not be an instance method on the decorator itself,
// 655:       # otherwise we'd have to call child.decorator here, which would create the decorator
// 656:       # before any `decorator_class` override has a chance to take effect (see the comment below).
// 657:       T::Props::Plugin::Private.apply_class_methods(mod, child)
// 658:     end
// 659:
// 660:     parent_props = props
// 661:     # Return before child.decorator below: forcing decorator creation for a
// 662:     # prop-less parent would defeat any decorator_class override (see the NB).
// 663:     return if parent_props.empty?
// 664:
// 665:     # NB: Calling `child.decorator` here is a time bomb that's going to give someone a really bad
// 666:     # time. Any class that defines props and also overrides the `decorator_class` method is going
// 667:     # to reach this line before its override take effect, turning it into a no-op.
// 668:     child_decorator = child.decorator
// 669:
// 670:     # Computed once for all props: the owner comparison cannot change inside
// 671:     # the loop below (it only defines prop accessors on child), and each
// 672:     # Object#method call allocates a fresh Method.
// 673:     clobber_getters = child_decorator.method(:prop_get).owner != method(:prop_get).owner
// 674:     clobber_setters = child_decorator.method(:prop_set).owner != method(:prop_set).owner
// 675:
// 676:     parent_props.each do |name, rules|
// 677:       copied_rules = rules.dup
// 678:       child_decorator.add_prop_definition(name, copied_rules)
// 679:
// 680:       # It's a bit tricky to support `prop_get` hooks added by plugins without
// 681:       # sacrificing the `attr_reader` fast path or clobbering customized getters
// 682:       # defined manually on a child.
// 683:       #
// 684:       # To make this work, we _do_ clobber getters defined on the child, but only if:
// 685:       # (a) it's needed in order to support a `prop_get` hook, and
// 686:       # (b) it's safe because the getter was defined by this file.
// 687:       #
// 688:       unless rules[:without_accessors]
// 689:         if clobber_getters && child.instance_method(name).source_location&.first == __FILE__
// 690:           child.send(:define_method, name) do
// 691:             T.unsafe(self.class).decorator.prop_get(self, name, rules)
// 692:           end
// 693:         end
// 694:
// 695:         if !rules[:immutable] && clobber_setters && child.instance_method("#{name}=").source_location&.first == __FILE__
// 696:           child.send(:define_method, "#{name}=") do |val|
// 697:             T.unsafe(self.class).decorator.prop_set(self, name, val, rules)
// 698:           end
// 699:         end
// 700:       end
// 701:     end
// 702:   end
// 703:
// 704:   sig(:final) do
// 705:     params(key: Symbol, d: T.untyped, out: T::Hash[Symbol, {allow_incompatible: T::Boolean}])
// 706:       .void
// 707:       .checked(:never)
// 708:   end
// 709:   private def elaborate_override_entry(key, d, out)
// 710:     # It's written this way so that `{reader: false}` will omit the entry for `reader` in the
// 711:     # result entirely
// 712:     case d[key]
// 713:     when TrueClass
// 714:       out[key] = {allow_incompatible: false}
// 715:     when Hash
// 716:       out[key] = {allow_incompatible: !!d[key][:allow_incompatible]}
// 717:     end
// 718:   end
// 719:
// 720:   sig(:final) do
// 721:     params(name: Symbol, d: T.untyped)
// 722:       .returns(T::Hash[Symbol, {allow_incompatible: T::Boolean}])
// 723:       .checked(:never)
// 724:   end
// 725:   private def elaborate_override(name, d)
// 726:     return OVERRIDE_TRUE if d == true
// 727:     return OVERRIDE_READER if d == :reader
// 728:     return OVERRIDE_WRITER if d == :writer
// 729:     return OVERRIDE_EMPTY if d == false || d.nil?
// 730:     unless d.is_a?(Hash)
// 731:       raise ArgumentError.new("`override` only accepts `true`, `:reader`, `:writer`, or a Hash in prop #{@class.name}.#{name} (got #{d.class})")
// 732:     end
// 733:
// 734:     # cwong: should we check for bad keys? `sig { override(not_real: true) }` on a normal function
// 735:     # errors statically but not at runtime.
// 736:
// 737:     # XX cwong: this means {reader: false, allow_incompatible: true} will become {allow_incompatible: true},
// 738:     # is that fine?
// 739:     unless (allow_incompatible = d[:allow_incompatible]).nil?
// 740:       return {reader: {allow_incompatible: !!allow_incompatible},
// 741:               writer: {allow_incompatible: !!allow_incompatible}}.to_h
// 742:     end
// 743:
// 744:     result = {}
// 745:     elaborate_override_entry(:reader, d, result)
// 746:     elaborate_override_entry(:writer, d, result)
// 747:     result
// 748:   end
// 749:
// 750:   sig { params(mod: T::Module[T.anything]).void.checked(:never) }
// 751:   def plugin(mod)
// 752:     decorated_class.plugins << mod
// 753:     T::Props::Plugin::Private.apply_class_methods(mod, decorated_class)
// 754:     T::Props::Plugin::Private.apply_decorator_methods(mod, self)
// 755:   end
// 756: end
